import assert from "node:assert/strict";
import { describe, test } from "node:test";
import { transactCalldata } from "./transaction";

describe("transactCalldata", () => {
  /* The expected bytes are cast's, 24 Sep 2026: `cast calldata "transact((bytes32,bytes32[2],bytes32[2],address,uint256,
     address,uint256),bytes,bytes)" "(0x01…01,[0x02…02,0x03…03],[0x04…04,0x05…05],0xd33d…d757,600,0x…b2,25)" 0x0707 0x0808`. */
  test("encodes the transaction as the pool's ABI does", () => {
    const word = (byte: string) => `0x${byte.repeat(32)}` as const;
    const calldata = transactCalldata(
      {
        root: word("01"),
        nullifiers: [word("02"), word("03")],
        commitments: [word("04"), word("05")],
        exitAsset: "0xd33de4d258d964b19ac83f4c80d81a0689a9d757",
        exitAmount: 600n,
        recipient: "0x00000000000000000000000000000000000000b2",
        fee: 25n,
      },
      "0x0707",
      "0x0808",
    );
    assert.equal(calldata, "");
  });
});
